const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const boston = ee.Geometry.Point([-71.0589, 42.3601]);
  const startDate = '2019-01-29';
  const endDate = '2019-02-06'; // Exclusive end date to include Feb 5

  // 2. Data Acquisition - ERA5-Land for 2m temperature
  const tempCollection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(boston)
    .select('temperature_2m');

  // Check collection size
  const collectionSize = tempCollection.size().getInfo();
  console.log(`ERA5-Land images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No temperature data available for the specified period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate daily maximum temperatures
  // Group by day and get max temperature for each day
  const dailyMax = tempCollection
    .map(function(image) {
      const date = image.date();
      const day = date.format('YYYY-MM-dd');
      return image.set('day', day);
    })
    .reduceColumns({
      reducer: ee.Reducer.max().group({
        groupField: 1,
        groupName: 'day'
      }),
      selectors: ['temperature_2m', 'day']
    });

  const dailyMaxTemps = dailyMax.get('groups').getInfo();
  console.log(`Days with data: ${dailyMaxTemps.length}`);

  if (dailyMaxTemps.length === 0) {
    console.log("No valid daily temperature data after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Extract temperature values (convert from Kelvin to Celsius)
  const tempsCelsius = dailyMaxTemps.map(group => group.max - 273.15);
  console.log(`Daily max temperatures (°C): ${tempsCelsius.map(t => t.toFixed(1)).join(', ')}`);

  // 4. Calculation - Find temperature range
  const maxTemp = Math.max(...tempsCelsius);
  const minTemp = Math.min(...tempsCelsius);
  const tempRange = maxTemp - minTemp;

  console.log(`Max temp: ${maxTemp.toFixed(1)}°C, Min temp: ${minTemp.toFixed(1)}°C`);
  console.log(`Temperature range: ${tempRange.toFixed(1)}°C`);

  // 5. Validation & Final Answer
  if (isNaN(tempRange) || !isFinite(tempRange) || tempRange < -100 || tempRange > 100) {
    console.log("Invalid temperature range calculated.");
    console.log("<answer>C3</answer>");
  } else if (tempRange >= 30) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
